    [ExcludeFromCodeCoverage]
    public class StudentAssessmentPutPostRequestValidator : FluentValidation.AbstractValidator<StudentAssessment>
    {
        protected override bool PreValidate(FluentValidation.ValidationContext<StudentAssessment> context, FluentValidation.Results.ValidationResult result)
        {
            if (context.InstanceToValidate == null)
            {
                result.Errors.Add(new ValidationFailure("", "Please ensure a model was supplied."));

                return false;
            }

            var instance = context.InstanceToValidate;

            var failures = new List<ValidationFailure>();

            // -----------------------
            //  Validate unified keys
            // -----------------------

            // Recursively invoke the child collection item validators
            var studentAssessmentStudentObjectiveAssessmentsValidator = new StudentAssessmentStudentObjectiveAssessmentPutPostRequestValidator();

            foreach (var item in instance.StudentAssessmentStudentObjectiveAssessments)
            {
                var validationResult = studentAssessmentStudentObjectiveAssessmentsValidator.Validate(item);

                if (!validationResult.IsValid)
                    failures.AddRange(validationResult.Errors);
            }


            if (failures.Any())
            {
                foreach (var failure in failures)
                {
                    result.Errors.Add(failure);
                }

                return false;
            }

            return true;
        }
    }
